    public int findMinArrowShots(int[][] points) {
        Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));  // compare() avoids overflow
        int arrows = 0;
        long pos = Long.MIN_VALUE;
        for (int[] p : points) if (p[0] > pos) { arrows++; pos = p[1]; }
        return arrows;
    }
